def custo_luna(uso: dict) -> float:
    ent, cache, sai = (uso.get("tokens_entrada") or 0), (uso.get("tokens_cache") or 0), (uso.get("tokens_saida") or 0)
    return ((ent - cache) * PRECO_LUNA["entrada"] + cache * PRECO_LUNA["cache"] + sai * PRECO_LUNA["saida"]) / 1e6

paredes.py:_reais.codigo:
def _reais(numero: str, escala: str | None) -> int | None:
    """'2.500' -> 2500; '2.500,00' -> 2500; '3' + 'mil' -> 3000; '1,2' + 'milhão' -> 1200000."""
    n = numero.strip(".")
    if not n:
        return None
    if "," in n:
        inteiro, dec = n.split(",", 1)
        v = float(inteiro.replace(".", "") + "." + dec)
    else:
        v = float(n.replace(".", ""))
    e = _sem_acento(escala or "").strip().lower()
    if e.startswith("mil") and not e.startswith("milh"):
        v *= 1000
    elif e.startswith("milh"):
        v *= 1_000_000
    return int(round(v))

